ALTER TABLE decision_readiness ENABLE ROW LEVEL SECURITY;
ALTER TABLE dependency_observation ENABLE ROW LEVEL SECURITY;
ALTER TABLE executive_timeline_entry ENABLE ROW LEVEL SECURITY;
ALTER TABLE advisory_request ENABLE ROW LEVEL SECURITY;
